import argparse,hashlib,importlib.util,json,sys,uuid
from pathlib import Path
sys.dont_write_bytecode=True
ROOT=Path(__file__).resolve().parents[1]
spec=importlib.util.spec_from_file_location('canonical18_gate',ROOT/'tools/verify-highway.py');gate=importlib.util.module_from_spec(spec);spec.loader.exec_module(gate);gate.__file__=__file__
boundary=" await page.locator('#ws-open-file').setInputFiles({name:'own-highway-study.json'"
assert gate.BROWSER.count(boundary)==1
prefix=gate.BROWSER[:gate.BROWSER.index(boundary)]
gate.BROWSER=prefix+r'''
 fixture.title='Original canonical18 native drum study';fixture.arrangements=fixture.arrangements.filter(a=>a.type==='drums');const part=fixture.arrangements[0];
 part.notes=[2,5,8,10].flatMap((time,i)=>[{id:'own-stack-'+i,time,piece:'stack',velocity:80,sustain:0,opaque:{own:'stack '+i}},{id:'own-bell-'+i,time:time+.3,piece:'bell',velocity:80,sustain:0,opaque:{own:'bell '+i}}]);part.chords=[];part.opaque={own:'part metadata'};part.activeDifficulty=0;part.difficulties=[{difficulty:0,notes:structuredClone(part.notes),chords:[],anchors:[],handshapes:[]},{difficulty:7,notes:[{id:'hidden-own',time:7,piece:'own-hidden',velocity:50}],chords:[],anchors:[],handshapes:[],opaque:{own:'hidden retained'}}];
 async function action(name){await page.locator(`[data-action="${name}"]`).first().evaluate(el=>el.click());}
 async function snapshot(){const pending=page.waitForEvent('download');await action('saveas');await page.locator('#ws-export-format').selectOption('json');await page.locator('#ws-dialog-submit').click();const chunks=[];for await(const chunk of await(await pending).createReadStream())chunks.push(chunk);return JSON.parse(Buffer.concat(chunks));}
 async function editorContext(){return page.evaluate(()=>({arrangement:document.querySelector('#ws-arrangement').value,difficulty:document.querySelector('#ws-difficulty').value,zoom:document.querySelector('#ws-zoom').value,scroll:document.querySelector('#ws-timeline-scroll').scrollLeft,view:document.querySelector('#ws-tab-view')?.hidden}));}
 await page.locator('#ws-open-file').setInputFiles({name:'own-native-canonical18.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(fixture))});await page.waitForFunction(title=>document.querySelector('#ws-title').textContent.includes(title),fixture.title);
 await page.locator('#ws-zoom').fill('210');await page.locator('#ws-zoom').dispatchEvent('input');await page.locator('#ws-timeline-scroll').evaluate(el=>el.scrollLeft=45);const source=await snapshot(),contextBefore=await editorContext();
 const writes=[];page.on('request',request=>{if(request.method()==='POST'&&['/api/plugins/open_chart_editor/save','/api/songs/upload'].some(path=>request.url().endsWith(path)))writes.push(request.url());});
 await page.evaluate(async()=>{window.__canonical18Meshes=[];const T=await import('/static/vendor/three/three.module.min.js'),original=T.Object3D.prototype.add;T.Object3D.prototype.add=function(...objects){const out=original.apply(this,objects);for(const object of objects){if(object.type!=='Group')continue;const gem=object.children?.find(mesh=>mesh.geometry?.type==='CylinderGeometry'&&mesh.geometry.parameters.radialSegments===8&&Math.abs(mesh.geometry.parameters.radiusTop/mesh.geometry.parameters.radiusBottom-.15)<.00001);if(!gem)continue;const row={x:object.position.x,z:object.position.z,types:object.children.map(m=>m.geometry?.type??m.type),bellDots:object.children.filter(m=>m.geometry?.type==='CircleGeometry'&&m.geometry.parameters.segments===16).length};if(window.__canonical18Meshes.length<512)window.__canonical18Meshes.push(row);}return out;};});
 const cases=[];
 for(const mode of ['default','own-lanes']){
  const kitBefore=await page.evaluate(mode=>{if(mode==='default')drumH3dResetKit();else if(!drumH3dSetKit({version:1,name:'Own explicit stack bell lanes',lanes:[{piece:'stack'},{piece:'bell'},{piece:'kick'}],fallbacks:{}}))throw Error('Own isolated kit refused');window.__canonical18Meshes=[];return drumH3dGetKit();},mode),socketStart=ws.length;
  await action('playtest-start');await page.waitForSelector('#player.active');await page.waitForFunction(()=>feedBack.playback.snapshot().state.transport.isPlaying&&feedBack.playback.snapshot().state.transport.readiness==='ready');
  await page.evaluate(async()=>{window.canonical18Module=await import('/api/plugins/open_chart_editor/src/playtest.js');});await page.waitForFunction(()=>canonical18Module.getPreviews().some(p=>p.status==='playing'));const started=await page.evaluate(()=>{window.canonical18Preview=canonical18Module.getPreviews().find(p=>p.status==='playing');return {time:feedBack.playback.snapshot().state.media.mediaTime,filename:canonical18Preview.filename};});await page.waitForFunction(t=>feedBack.playback.snapshot().state.media.mediaTime>t+.1,started.time);
  const hits=ws.slice(socketStart).flatMap(s=>s.payload).filter(m=>m.type==='drum_hits').flatMap(m=>m.data??[]);assert.deepEqual(hits.map(h=>[h.t,h.p,h.v]),part.notes.map(n=>[n.time,n.piece,n.velocity]));
  await page.waitForFunction(()=>window.__canonical18Meshes.some(m=>m.bellDots>0)&&window.__canonical18Meshes.some(m=>m.bellDots===0));const native=await page.evaluate(async()=>{const kit=await import('/api/plugins/drum_highway_3d/src/drum-kit.js'),constants=await import('/api/plugins/drum_highway_3d/src/drum-constants.js');return {kit:drumH3dGetKit(),pieces:drumH3dGetAllPieces(),lanes:kit.getLanes(),map:kit.getPieceToLane(),laneXs:{stack:kit.getLaneX0()+kit.getPieceToLane().stack*constants.LANE_GAP,bell:kit.getLaneX0()+kit.getPieceToLane().bell*constants.LANE_GAP},variants:['stack','bell'].map(p=>constants._variantForHit({p,v:80})),meshes:window.__canonical18Meshes,classic:highway.isDefaultRenderer(),label:document.querySelector('#viz-picker option[value="auto"]')?.textContent};});assert.equal(native.classic,false);assert.match(native.label,/3D/);assert.equal(native.pieces.length,18);assert.deepEqual(native.kit,kitBefore);assert.deepEqual(native.variants,['normal','bell']);for(const mesh of native.meshes)assert.ok(Math.abs(mesh.x-native.laneXs[mesh.bellDots?'bell':'stack'])<1e-6,'Actual native gem or bell dot rendered in wrong lane');if(mode==='default'){assert.equal(native.map.stack,native.map.crash_l);assert.equal(native.map.bell,native.map.ride);}else{assert.equal(native.lanes[native.map.stack].piece,'stack');assert.equal(native.lanes[native.map.bell].piece,'bell');}
  const canvasScreenshot=process.env.OCE_HIGHWAY_SCREENSHOT.replace('.png',`-${mode}-canvas.png`);await page.locator('#highway').screenshot({path:canvasScreenshot});await page.evaluate(async()=>canonical18Module.endPlaytest(canonical18Preview));await page.waitForTimeout(250);await page.evaluate(async()=>canonical18Module.removePreview(canonical18Preview));await page.waitForSelector('#plugin-open_chart_editor.active #ws-canvas');assert.deepEqual(await editorContext(),contextBefore);assert.deepEqual(await snapshot(),source);assert.deepEqual(await page.evaluate(()=>drumH3dGetKit()),kitBefore);cases.push({mode,drumHits:hits,native,canvasScreenshot,canvasPixels:null,contextRestored:true,allDdAndOpaqueExact:true,kitUnchanged:true,ownedPreviewRemoved:true});
 }
 const ownOmission=await page.evaluate(()=>{drumH3dSetKit({version:1,name:'Own deliberate omissions',lanes:[{piece:'kick'}],fallbacks:{}});return drumH3dGetKit();}),writeCount=writes.length;await action('playtest-start');await page.waitForFunction(()=>/cannot display this visible chart/.test(document.querySelector('#ws-status').textContent));assert.match(await page.locator('#ws-status').textContent(),/assign.*reset/);assert.equal(writes.length,writeCount);assert.deepEqual(await page.evaluate(()=>drumH3dGetKit()),ownOmission);assert.deepEqual(await editorContext(),contextBefore);assert.deepEqual(await snapshot(),source);
 const isolation=await(await page.request.get(process.env.OCE_HOST_URL+'/harness/isolation')).json();assert.deepEqual(isolation.entries,[]);const ancillaryCoreFailures=httpErrors.filter(item=>!['/api/plugins/minigames/profile','/api/plugins/minigames/registry','/api/plugins/tuner/config'].some(path=>item.url.endsWith(path)));assert.deepEqual(errors,[]);assert.deepEqual(ancillaryCoreFailures,[]);console.log(JSON.stringify({ok:true,playbackPassed:true,fullShellClean:true,cases,omission:{refusedBeforeSaveOrUpload:true,kitUnchanged:true,allSourceExact:true},isolation,errors,httpErrors,ancillaryCoreFailures,blockedExternalOrigins:[...new Set(blocked)],physicalHardwareVerified:false}));
}catch(error){console.error(JSON.stringify({error:String(error),errors,httpErrors,blocked,websockets:ws}));throw error;}
finally{await page.screenshot({path:process.env.OCE_HIGHWAY_SCREENSHOT}).catch(()=>{});await browser.close();}
'''
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--serve',action='store_true');p.add_argument('--host-root',type=Path,default=gate.HOST);p.add_argument('--run-dir',type=Path);p.add_argument('--port',type=int,default=0);p.add_argument('--released-after-soak',action='store_true');a=p.parse_args()
 if a.serve:
  if not a.run_dir or not gate.install_module().within(a.run_dir,ROOT/'tools/.host-runs'):raise ValueError('Workspace run directory required')
  import uvicorn
  uvicorn.run(gate.make_app(a.host_root,a.run_dir),host='127.0.0.1',port=a.port,log_level='warning');return 0
 if not a.released_after_soak:raise ValueError('Browser held for controlled audio soak; parent must release explicitly')
 installed=json.loads((ROOT/'research/drum-canonical18/installed.json').read_text());constants=Path(installed['target']);digest=hashlib.sha256(constants.read_bytes()).hexdigest()
 if digest!=installed['candidateSha256']:raise ValueError('Installed canonical18 provider changed')
 run=ROOT/'tools/.host-runs'/uuid.uuid4().hex;run.mkdir()
 try:
  result=gate.verify(a.host_root,run);current=gate.install_module().make_plan(run/'plugins/open_chart_editor');result['sourceStable']=current['sourceDigest']==result['sourceDigest'];result['nativeConstantsSha256']=digest;result['nativeProviderManifestUnchanged']=hashlib.sha256(Path(installed['manifest']).read_bytes()).hexdigest()==installed['manifestSha256'];result['ok']=result['ok']and result['sourceStable']and result['nativeProviderManifestUnchanged']and hashlib.sha256(constants.read_bytes()).hexdigest()==digest
 except Exception as error:result={'ok':False,'error':str(error),'runDirectory':str(run)}
 (run/'report.json').write_text(json.dumps(result,indent=2));(ROOT/'research/drum-canonical18/native-highway-report.json').write_text(json.dumps(result,indent=2));print(json.dumps({'ok':result['ok'],'runDirectory':str(run),'sourceDigest':result.get('sourceDigest'),'error':result.get('error')},indent=2));return 0 if result['ok']else 1
if __name__=='__main__':raise SystemExit(main())
